   326	        (void)fseek((FILE*)mat->fp,-(int)matvar->internal->z->avail_in,SEEK_CUR);
   327	        bytesread -= matvar->internal->z->avail_in;
   328	        matvar->internal->z->avail_in = 0;
   329	    }
